handlers.reloadSearchGrid:
function reloadSearchGrid(event) {
			var intCode = $("#gs_intCode").val();
			reqJsonMap = {};
			respJsonMaps = {};

			if($("#gs_documentNo").val() == "" && $("#gs_referenceNo").val() == "" && $("#gs_referenceNo2").val() == ""){

				if($("#fromUpdDate").val() == "" || $("#toUpdDate").val() == ""){
					tryFocusBS($("#gs_updDate"));
					$("#gs_updDate").attr("readonly", false);
					window.parent.showAlert('Transaction date is mandatory');
					return false;
				}
				var retVal = $.ajax({
					url : "validateDateRange",

					type : "POST",
					data : {
				  		fromDateValue : $("#fromUpdDate").val(),
				    	toDateValue : $("#toUpdDate").val(),
						fieldName : "Txn "
					},
						dataType : "json",
						async : false
				}).responseText;
				retVal = jQuery.parseJSON(retVal);
				if(retVal != null){
					if(retVal.jsonMessage == null){

					} else {
						window.parent.showAlert(retVal.jsonMessage);
						event.preventDefault();
						return false;
					}
				}	
			}
			var retVal = $("#taxSettingLogTable").jqGrid('setGridParam', {
				datatype : 'json',
				page : 1,
				postData : {
					intCode			:$("#gs_intCode").val(),
					documentNo		:$("#gs_documentNo").val(),
					referenceNo		:$("#gs_referenceNo").val(),
					status			:$("#gs_status").val(),
					errorDesc		:$("#gs_errorDesc").val(),
					fromUpdDate		:$("#fromUpdDate").val(),
					toUpdDate		:$("#toUpdDate").val(),
					clientId		:$("#gs_clientId").val(),
					key1			:$("#gs_key1").val(),
					key2			:$("#gs_key2").val(),
					key3			:$("#gs_key3").val(),
					referenceNo2	:$("#gs_referenceNo2").val(),
					referenceType	:$("#gs_referenceType").val(),
					integrationType :$("#gs_integrationType").val(),
					REQ_SEARCH_FLAG : true
				},
				url : "jsonTaxTransmitLogSearch",
				search : true				
			}).trigger('reloadGrid');
		}

handlers.saveAddressData:
function saveAddressData(){
			if($("#custNameId").val() != null && $("#custNameId").val().trim() == ""){
				tryFocusBS($("#custNameId"));
				window.parent.showAlert('Customer Name' +' '+'is Mandatory.');
				return false;
			}
			if($("#custadd1Id").val() != null && $("#custadd1Id").val().trim() == ""){
				tryFocusBS($("#custadd1Id"));
				window.parent.showAlert('Ship to Address1 is mandatory');
				return false;
			}
			if($("#shipCountryId").val() != null && $("#shipCountryId").val() == "-1"){
				tryFocusBS($("#shipCountryId"));
				window.parent.showAlert('Ship to Country is mandatory');
				return false;
			}
			if($("#custphoneid").val() != null && $("#custphoneid").val().trim() == ""){
				tryFocusBS($("#custphoneid"));
				window.parent.showAlert('Ship to Phone is mandatory');
				return false;
			}
			if($("#custToStateId").val() != null && $("#custToStateId").val() == "-1"){   
				tryFocusBS($("#custToStateId"));
				window.parent.showAlert('Ship to State is mandatory');
				return false;
			}

			if($("#custPinCodeId").val() != null && $("#custPinCodeId").val().trim() == ""){
				tryFocusBS($("#custPinCodeId"));
				window.parent.showAlert('Ship to Pincode is mandatory');
				return false;
			}
			if($("#custEmailId").val() != null && $("#custEmailId").val().trim() == ""){
				tryFocusBS($("#custEmailId"));
				window.parent.showAlert('Ship to Email is mandatory');
				return false;
			}

			//-----------------------
			if($("#billNameId").val() != null && $("#billNameId").val().trim() == ""){
				tryFocusBS($("#billNameId"));
				window.parent.showAlert('Bill to Name is mandatory');
				return false;
			}
			if($("#billadd1Id").val() != null && $("#billadd1Id").val().trim() == ""){
				tryFocusBS($("#billadd1Id"));
				window.parent.showAlert('Bill to Address1 is mandatory');
				return false;
			}
			if($("#billphoneId").val() != null && $("#billphoneId").val() == ""){
				tryFocusBS($("#billphoneId"));
				window.parent.showAlert('Bill to Phone is mandatory');
				return false;
			}
			if($("#billcountryid").val() != null && $("#billcountryid").val() == "-1"){   
				tryFocusBS($("#billcountryid"));
				window.parent.showAlert('Bill to Country is mandatory');
				return false;
			}
			if($("#billstateId").val() != null && $("#billstateId").val().trim() == "-1"){
				tryFocusBS($("#billstateId"));
				window.parent.showAlert('Bill to State is mandatory');
				return false;
			}
			 if($("#billpincodeId").val() != null && $("#billpincodeId").val().trim() == ""){
				tryFocusBS($("#billpincodeId"));
				window.parent.showAlert('Bill to Pincode is mandatory');
				return false;
			}
			 if($("#billgstnoid").val() != null && $("#billgstnoid").val() == ""){
					tryFocusBS($("#billgstnoid"));
					window.parent.showAlert('Customer GSTIN/TIN'+' '+'is Mandatory.');
					return false;
			}
			 if($("#billgstnoid").val() != null && $("#billgstnoid").val().trim() != "" && $("#billgstnoid").val().trim() != undefined 
					 && $("#billgstnoid").val().trim().toLocaleUpperCase() != "URP" && $("#billgstnoid").val().length != '15'){
					tryFocusBS($("#billgstnoid"));
					window.parent.showAlert('GSTIN No must be 15 characters');
					return false;
				}
			if($("#billEmailId").val() != null && $("#billEmailId").val().trim() == ""){
				tryFocusBS($("#billEmailId"));
				window.parent.showAlert('Bill to Email is mandatory');
				return false;
			}

			var emailaddressVal = $("#billEmailId").val();
		    var emailReg = /^([\w-\.]+@([\w-]+\.)+[\w-]{2,10})?$/; 

		    if(!emailReg.test(emailaddressVal)){
		    	window.parent.showAlert('Bill to Email is not a valid address.');
				tryFocus($("#billEmailId"));			
		        return false; 
		    }
		    if(!emailReg.test($("#custEmailId").val())){
		    	window.parent.showAlert('Ship to Email is not a valid address.');
				tryFocus($("#custEmailId"));			
		        return false; 
		    }

		    if(isNotBlank($("#shipGstin").val()) && $("#shipGstin").val().trim().toLocaleUpperCase() != "URP" && $("#shipGstin").val().length != '15'){
					tryFocusBS($("#shipGstin"));
					window.parent.showAlert('GSTIN No must be 15 characters');
					return false;
			}

			var retVal = $.ajax({
				url : "updateOrderAddressDetails",

				type : "POST",
				data : {
					shipCustname : $("#custNameId").val(),
					shipAddss1 : $("#custadd1Id").val(),
					shipAddss2 : $("#custadd2Id").val(),
					shipAddss3 : $("#custadd3Id").val(),
					shipAddss4 : $("#custadd4Id").val(),
					shipPhone : $("#custphoneid").val(),
					shipPinCode : $("#custPinCodeId").val(),
					shipCity : $("#custCityId").val(),
					shipEmail : $("#custEmailId").val(),
					billCustname : $("#billNameId").val(),
					billAddss1 : $("#billadd1Id").val(),
					billAddss2 : $("#billadd2Id").val(),
					billAddss3 : $("#billadd3Id").val(),
					billAddss4 : $("#billadd4Id").val(),
					billPhone : $("#billphoneId").val(),
					billPinCode : $("#billpincodeId").val(),
					billCity : $("#billcityId").val(),
					billEmail : $("#billEmailId").val(),   
					billGstIN : $("#billgstnoid").val(),
					 orderno : $('#hiddnOrderNo').val(),
					 obdelNo : $('#hiddnObCode').val(),
					 transKey : $('#hiddentransKey').val(),
					 intCode  : $('#hiddenIntCode').val(),
					 shipGstIn : $("#shipGstin").val()
				},
				dataType : "json",
				async : false
			}).responseText;

			retVal = jQuery.parseJSON(retVal);
			if(retVal != null && retVal.jsonMessage != null && retVal.jsonMessage != ""){
				window.parent.blockUIEnd();
				window.parent.showAlert(retVal.jsonMessage);
				return false;
			}else{
				$("#addressDialogPopUp").modal("hide");
				if($('#hiddenIntCode').val() != null && $('#hiddenIntCode').val()== "EWB_GEN")
					window.parent.showAlert('Record Updated Successfully');
				else
				window.parent.showAlert('Record Updated Successfully'+' & '+'Records Repushed Successfully');
				jQuery("#taxSettingLogTable").trigger("reloadGrid");
				return false;
		}

		}
